    UnboundedSource<Long, Checkpoint<Long>> unboundedSource = new BoundedToUnboundedSourceAdapter<>(boundedSource);
    PCollection<Long> output = p.apply(Read.from(unboundedSource).withMaxNumRecords(numElements));
    // Count == numElements
    PAssert.thatSingleton(output.apply("Count", Count.<Long>globally())).isEqualTo(numElements);
    // Unique count == numElements
    PAssert.thatSingleton(output.apply(Distinct.<Long>create()).apply("UniqueCount", Count.<Long>globally())).isEqualTo(numElements);
    // Min == 0
    PAssert.thatSingleton(output.apply("Min", Min.<Long>globally())).isEqualTo(0L);
    // Max == numElements-1
    PAssert.thatSingleton(output.apply("Max", Max.<Long>globally())).isEqualTo(numElements - 1);
    p.run();
}

