    // Revisit the same session window.
    tester.injectElements(TimestampedValue.of(1, new Instant(1)), TimestampedValue.of(2, new Instant(2)));
    // Trigger is still closed.
    assertTrue(tester.isMarkedFinished(mergedWindow));
