    when(fnApiControlClient.handle(any(BeamFnApi.InstructionRequest.class))).thenReturn(registerResponseFuture);
    Future<BeamFnApi.RegisterResponse> responseFuture = sdkHarnessClient.register(ImmutableList.of(BeamFnApi.ProcessBundleDescriptor.newBuilder().setId(descriptorId1).build(), BeamFnApi.ProcessBundleDescriptor.newBuilder().setId(descriptorId2).build()));
