    assertEquals(-1, s.find(buffer, buffer.length));
    buffer = new byte[] { 2 };
    assertEquals(-1, s.find(buffer, buffer.length));
    buffer = new byte[] { 3 };
    assertEquals(0, s.find(buffer, buffer.length));
}

