@Test
@Category(NeedsRunner.class)
public void testWindowedWritesWithOnceTrigger() throws Throwable {
    // Tests for https://issues.apache.org/jira/browse/BEAM-3169
    PCollection<String> data = p.apply(Create.of("0", "1", "2")).apply(Window.<String>into(FixedWindows.of(Duration.standardSeconds(1))).// According to this trigger, all data should be written.
    // However, the continuation of this trigger is elementCountAtLeast(1),
    // so with a buggy implementation that used a GBK before renaming files,
    // only 1 file would be renamed.
    triggering(AfterPane.elementCountAtLeast(3)).withAllowedLateness(Duration.standardMinutes(1)).discardingFiredPanes());
    PCollection<String> filenames = data.apply(TextIO.write().to(new File(tempFolder.getRoot(), "windowed-writes").getAbsolutePath()).withNumShards(2).withWindowedWrites().<Void>withOutputFilenames()).getPerDestinationOutputFilenames().apply(Values.<String>create());
    PAssert.that(filenames.apply(TextIO.readAll())).containsInAnyOrder("0", "1", "2");
    p.run();
}

