@Test
@Category(ValidatesRunner.class)
public void testGroupByKeyAndWindows() {
    List<KV<String, Integer>> ungroupedPairs = Arrays.asList(// window [0, 5)
    KV.of("k1", 3), // window [0, 5)
    KV.of("k5", Integer.MAX_VALUE), // window [0, 5)
    KV.of("k5", Integer.MIN_VALUE), // window [0, 5)
    KV.of("k2", 66), // window [5, 10)
    KV.of("k1", 4), // window [5, 10)
    KV.of("k2", -33), // window [5, 10)
    KV.of("k3", 0));
    PCollection<KV<String, Integer>> input = p.apply(Create.timestamped(ungroupedPairs, Arrays.asList(1L, 2L, 3L, 4L, 5L, 6L, 7L)).withCoder(KvCoder.of(StringUtf8Coder.of(), BigEndianIntegerCoder.of())));
    PCollection<KV<String, Iterable<Integer>>> output = input.apply(Window.<KV<String, Integer>>into(FixedWindows.of(new Duration(5)))).apply(GroupByKey.<String, Integer>create());
    PAssert.that(output).satisfies(containsKvs(kv("k1", 3), kv("k1", 4), kv("k5", Integer.MAX_VALUE, Integer.MIN_VALUE), kv("k2", 66), kv("k2", -33), kv("k3", 0)));
    PAssert.that(output).inWindow(new IntervalWindow(new Instant(0L), Duration.millis(5L))).satisfies(containsKvs(kv("k1", 3), kv("k5", Integer.MIN_VALUE, Integer.MAX_VALUE), kv("k2", 66)));
    PAssert.that(output).inWindow(new IntervalWindow(new Instant(5L), Duration.millis(5L))).satisfies(containsKvs(kv("k1", 4), kv("k2", -33), kv("k3", 0)));
    p.run();
}

