/**
 * Verify that runners correctly hash/group on the encoded value
 * and not the value itself.
 */
@Test
@Category(ValidatesRunner.class)
public void testGroupByKeyWithBadEqualsHashCode() throws Exception {
    final int numValues = 10;
    final int numKeys = 5;
    p.getCoderRegistry().registerCoderProvider(CoderProviders.fromStaticMethods(BadEqualityKey.class, DeterministicKeyCoder.class));
    // construct input data
    List<KV<BadEqualityKey, Long>> input = new ArrayList<>();
    for (int i = 0; i < numValues; i++) {
        for (int key = 0; key < numKeys; key++) {
            input.add(KV.of(new BadEqualityKey(key), 1L));
        }
    }
    // We first ensure that the values are randomly partitioned in the beginning.
    // Some runners might otherwise keep all values on the machine where
    // they are initially created.
    PCollection<KV<BadEqualityKey, Long>> dataset1 = p.apply(Create.of(input)).apply(ParDo.of(new AssignRandomKey())).apply(Reshuffle.<Long, KV<BadEqualityKey, Long>>of()).apply(Values.<KV<BadEqualityKey, Long>>create());
    // Make the GroupByKey and Count implicit, in real-world code
    // this would be a Count.perKey()
    PCollection<KV<BadEqualityKey, Long>> result = dataset1.apply(GroupByKey.<BadEqualityKey, Long>create()).apply(Combine.<BadEqualityKey, Long>groupedValues(new CountFn()));
    PAssert.that(result).satisfies(new AssertThatCountPerKeyCorrect(numValues));
    PAssert.that(result.apply(Keys.<BadEqualityKey>create())).satisfies(new AssertThatAllKeysExist(numKeys));
    p.run();
}

