@Test
@Category(ValidatesRunner.class)
public void testParDoShiftTimestampUnlimited() {
    PCollection<Long> outputs = pipeline.apply(Create.of(Arrays.asList(0L, BoundedWindow.TIMESTAMP_MIN_VALUE.getMillis(), GlobalWindow.INSTANCE.maxTimestamp().getMillis()))).apply("AssignTimestampToValue", ParDo.of(new TestOutputTimestampDoFn<Long>())).apply("ReassignToMinimumTimestamp", ParDo.of(new DoFn<Long, Long>() {

        @ProcessElement
        public void reassignTimestamps(ProcessContext context) {
            // Shift the latest element as far backwards in time as the model permits
            context.outputWithTimestamp(context.element(), BoundedWindow.TIMESTAMP_MIN_VALUE);
        }

        @Override
        public Duration getAllowedTimestampSkew() {
            return Duration.millis(Long.MAX_VALUE);
        }
    }));
    PAssert.that(outputs).satisfies(new SerializableFunction<Iterable<Long>, Void>() {

        @Override
        public Void apply(Iterable<Long> input) {
            // This element is not shifted backwards in time. It must be present in the output.
            assertThat(input, hasItem(BoundedWindow.TIMESTAMP_MIN_VALUE.getMillis()));
            for (Long elem : input) {
                // Sanity check the outputs. 0L and the end of the global window are shifted
                // backwards in time and theoretically could be dropped.
                assertThat(elem, anyOf(equalTo(BoundedWindow.TIMESTAMP_MIN_VALUE.getMillis()), equalTo(GlobalWindow.INSTANCE.maxTimestamp().getMillis()), equalTo(0L)));
            }
            return null;
        }
    });
    pipeline.run();
}

