@Test
@Category(ValidatesRunner.class)
public void testReshufflePreservesTimestamps() {
    PCollection<KV<String, TimestampedValue<String>>> input = pipeline.apply(Create.timestamped(TimestampedValue.of("foo", BoundedWindow.TIMESTAMP_MIN_VALUE), TimestampedValue.of("foo", new Instant(0)), TimestampedValue.of("bar", new Instant(33)), TimestampedValue.of("bar", GlobalWindow.INSTANCE.maxTimestamp())).withCoder(StringUtf8Coder.of())).apply(WithKeys.of(new SerializableFunction<String, String>() {

        @Override
        public String apply(String input) {
            return input;
        }
    })).apply("ReifyOriginalTimestamps", Reify.<String, String>timestampsInValue());
    // The outer TimestampedValue is the reified timestamp post-reshuffle. The inner
    // TimestampedValue is the pre-reshuffle timestamp.
    PCollection<TimestampedValue<TimestampedValue<String>>> output = input.apply(Reshuffle.<String, TimestampedValue<String>>of()).apply("ReifyReshuffledTimestamps", Reify.<String, TimestampedValue<String>>timestampsInValue()).apply(Values.<TimestampedValue<TimestampedValue<String>>>create());
    PAssert.that(output).satisfies(new SerializableFunction<Iterable<TimestampedValue<TimestampedValue<String>>>, Void>() {

        @Override
        public Void apply(Iterable<TimestampedValue<TimestampedValue<String>>> input) {
            for (TimestampedValue<TimestampedValue<String>> elem : input) {
                Instant originalTimestamp = elem.getValue().getTimestamp();
                Instant afterReshuffleTimestamp = elem.getTimestamp();
                assertThat("Reshuffle must preserve element timestamps", afterReshuffleTimestamp, equalTo(originalTimestamp));
            }
            return null;
        }
    });
    pipeline.run();
}

