@Test
@Category({ NeedsRunner.class, UsesSplittableParDo.class })
public void testSinglePollWithManyResults() {
    // More than the default 100 elements per checkpoint for direct runner.
    final long numResults = 3000;
    PCollection<KV<String, Integer>> res = p.apply(Create.of("a")).apply(Watch.growthOf(new PollFn<String, KV<String, Integer>>() {

        @Override
        public PollResult<KV<String, Integer>> apply(String element, Context c) throws Exception {
            String pollId = UUID.randomUUID().toString();
            List<KV<String, Integer>> output = Lists.newArrayList();
            for (int i = 0; i < numResults; ++i) {
                output.add(KV.of(pollId, i));
            }
            return PollResult.complete(Instant.now(), output);
        }
    }).withTerminationPerInput(Watch.Growth.<String>afterTotalOf(standardSeconds(1))).withPollInterval(Duration.millis(1)).withOutputCoder(KvCoder.of(StringUtf8Coder.of(), VarIntCoder.of()))).apply("Drop input", Values.<KV<String, Integer>>create());
    PAssert.that("Poll called only once", res.apply(Keys.<String>create())).satisfies(new SerializableFunction<Iterable<String>, Void>() {

        @Override
        public Void apply(Iterable<String> pollIds) {
            assertEquals(1, Sets.newHashSet(pollIds).size());
            return null;
        }
    });
    PAssert.that("Yields all expected results", res.apply("Drop poll id", Values.<Integer>create())).satisfies(new SerializableFunction<Iterable<Integer>, Void>() {

        @Override
        public Void apply(Iterable<Integer> input) {
            assertEquals("Total number of results mismatches", numResults, Lists.newArrayList(input).size());
            assertEquals("Results are not unique", numResults, Sets.newHashSet(input).size());
            return null;
        }
    });
    p.run();
}

@Test
@Category({ NeedsRunner.class, UsesSplittableParDo.class })
public void testMultiplePollsWithManyResults() {
    final long numResults = 3000;
    List<Integer> all = Lists.newArrayList();
    for (int i = 0; i < numResults; ++i) {
        all.add(i);
    }
    PCollection<TimestampedValue<Integer>> res = p.apply(Create.of("a")).apply(Watch.growthOf(new TimedPollFn<String, Integer>(all, standardSeconds(1), /* timeToOutputEverything */
    standardSeconds(3), /* timeToDeclareOutputFinal */
    standardSeconds(30))).withPollInterval(Duration.millis(500)).withOutputCoder(VarIntCoder.of())).apply(Reify.<String, Integer>timestampsInValue()).apply("Drop timestamped input", Values.<TimestampedValue<Integer>>create());
    PAssert.that(res).satisfies(new SerializableFunction<Iterable<TimestampedValue<Integer>>, Void>() {

        @Override
        public Void apply(Iterable<TimestampedValue<Integer>> outputs) {
            Function<TimestampedValue<Integer>, Integer> extractValueFn = new Function<TimestampedValue<Integer>, Integer>() {

                @Nullable
                @Override
                public Integer apply(@Nullable TimestampedValue<Integer> input) {
                    return input.getValue();
                }
            };
            Function<TimestampedValue<Integer>, Instant> extractTimestampFn = new Function<TimestampedValue<Integer>, Instant>() {

                @Nullable
                @Override
                public Instant apply(@Nullable TimestampedValue<Integer> input) {
                    return input.getTimestamp();
                }
            };
            Ordering<TimestampedValue<Integer>> byValue = Ordering.natural().onResultOf(extractValueFn);
            Ordering<TimestampedValue<Integer>> byTimestamp = Ordering.natural().onResultOf(extractTimestampFn);
            // New outputs appear in timestamp order because each output's assigned timestamp
            // is Instant.now() at the time of poll.
            assertTrue("Outputs must be in timestamp order", byTimestamp.isOrdered(byValue.sortedCopy(outputs)));
            assertEquals("Yields all expected values", Sets.newHashSet(Iterables.transform(outputs, extractValueFn)).size(), numResults);
            assertThat("Poll called more than once", Sets.newHashSet(Iterables.transform(outputs, extractTimestampFn)).size(), greaterThan(1));
            return null;
        }
    });
    p.run();
}

