        residualTracker.addNewAsPending(PollResult.incomplete(Arrays.asList(TimestampedValue.of("e", now.plus(standardSeconds(5))), TimestampedValue.of("d", now.plus(standardSeconds(4))), TimestampedValue.of("c", now.plus(standardSeconds(3))), TimestampedValue.of("a", now.plus(standardSeconds(1))), TimestampedValue.of("b", now.plus(standardSeconds(2))), TimestampedValue.of("f", now.plus(standardSeconds(8))))));
