@Test
@Category(ValidatesRunner.class)
public void testNoWindowFnDoesNotReassignWindows() {
    pipeline.enableAbandonedNodeEnforcement(true);
    final PCollection<Long> initialWindows = pipeline.apply(GenerateSequence.from(0).to(10)).apply("AssignWindows", Window.into(new WindowOddEvenBuckets()));
    // Sanity check the window assignment to demonstrate the baseline
    PAssert.that(initialWindows).inWindow(WindowOddEvenBuckets.EVEN_WINDOW).containsInAnyOrder(0L, 2L, 4L, 6L, 8L);
    PAssert.that(initialWindows).inWindow(WindowOddEvenBuckets.ODD_WINDOW).containsInAnyOrder(1L, 3L, 5L, 7L, 9L);
    PCollection<Boolean> upOne = initialWindows.apply("ModifyTypes", MapElements.<Long, Boolean>via(new SimpleFunction<Long, Boolean>() {

        @Override
        public Boolean apply(Long input) {
            return input % 2 == 0;
        }
    }));
    PAssert.that(upOne).inWindow(WindowOddEvenBuckets.EVEN_WINDOW).containsInAnyOrder(true, true, true, true, true);
    PAssert.that(upOne).inWindow(WindowOddEvenBuckets.ODD_WINDOW).containsInAnyOrder(false, false, false, false, false);
    // The elements should be in the same windows, even though they would not be assigned to the
    // same windows with the updated timestamps. If we try to apply the original WindowFn, the type
    // will not be appropriate and the runner should crash, as a Boolean cannot be converted into
    // a long.
    PCollection<Boolean> updatedTrigger = upOne.apply("UpdateWindowingStrategy", Window.<Boolean>configure().triggering(Never.ever()).withAllowedLateness(Duration.ZERO).accumulatingFiredPanes());
    pipeline.run();
}

