@Test
public void testNonDeterministicProperty() throws CoderException {
    MessageWithMap.Builder msg1B = MessageWithMap.newBuilder();
    MessageWithMap.Builder msg2B = MessageWithMap.newBuilder();
    // Built in reverse order but with equal contents.
    for (int i = 0; i < 10; ++i) {
        msg1B.getMutableField1().put("key" + i, MessageA.getDefaultInstance());
        msg2B.getMutableField1().put("key" + (9 - i), MessageA.getDefaultInstance());
    }
    // Assert the messages are equal.
    MessageWithMap msg1 = msg1B.build();
    MessageWithMap msg2 = msg2B.build();
    assertEquals(msg2, msg1);
    // Assert the encoded messages are not equal.
    Coder<MessageWithMap> coder = ProtoCoder.of(MessageWithMap.class);
    assertNotEquals(CoderUtils.encodeToBase64(coder, msg2), CoderUtils.encodeToBase64(coder, msg1));
}

@Test
public void smallCardinality() {
    final int smallCard = 1000;
    final int p = 6;
    final double expectedErr = 1.104 / Math.sqrt(p);
    List<Integer> small = new ArrayList<>();
    for (int i = 0; i < smallCard; i++) {
        small.add(i);
    }
    PCollection<Long> cardinality = tp.apply("small stream", Create.<Integer>of(small)).apply("small cardinality", ApproximateDistinct.<Integer>globally().withPrecision(p));
    PAssert.that("Not Accurate Enough", cardinality).satisfies(new VerifyAccuracy(smallCard, expectedErr));
    tp.run();
}

@Test
public void bigCardinality() {
    final int cardinality = 15000;
    final int p = 15;
    final int sp = 20;
    final double expectedErr = 1.04 / Math.sqrt(p);
    List<Integer> stream = new ArrayList<>();
    for (int i = 1; i <= cardinality; i++) {
        stream.addAll(Collections.nCopies(2, i));
    }
    Collections.shuffle(stream);
    PCollection<Long> res = tp.apply("big stream", Create.<Integer>of(stream)).apply("big cardinality", ApproximateDistinct.<Integer>globally().withPrecision(p).withSparsePrecision(sp));
    PAssert.that("Verify Accuracy for big cardinality", res).satisfies(new VerifyAccuracy(cardinality, expectedErr));
    tp.run();
}

