@Test
public void testBuildExpression_string() {
    RexNode rexNode;
    BeamSqlExpression exp;
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.CONCAT, Arrays.asList(rexBuilder.makeLiteral("hello "), rexBuilder.makeLiteral("world")));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
