    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.POSITION, Arrays.asList(rexBuilder.makeLiteral("hello"), rexBuilder.makeLiteral("worldhello")));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
