    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.POSITION, Arrays.asList(rexBuilder.makeLiteral("hello"), rexBuilder.makeLiteral("worldhello"), rexBuilder.makeCast(BeamQueryPlanner.TYPE_FACTORY.createSqlType(SqlTypeName.INTEGER), rexBuilder.makeBigintLiteral(BigDecimal.ONE))));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlPositionExpression);
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.CHAR_LENGTH, Arrays.asList(rexBuilder.makeLiteral("hello")));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlCharLengthExpression);
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.UPPER, Arrays.asList(rexBuilder.makeLiteral("hello")));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlUpperExpression);
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.LOWER, Arrays.asList(rexBuilder.makeLiteral("HELLO")));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlLowerExpression);
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.INITCAP, Arrays.asList(rexBuilder.makeLiteral("hello")));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlInitCapExpression);
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.TRIM, Arrays.asList(rexBuilder.makeFlag(SqlTrimFunction.Flag.BOTH), rexBuilder.makeLiteral("HELLO"), rexBuilder.makeLiteral("HELLO")));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlTrimExpression);
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.SUBSTRING, Arrays.asList(rexBuilder.makeLiteral("HELLO"), rexBuilder.makeBigintLiteral(BigDecimal.ZERO)));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlSubstringExpression);
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.SUBSTRING, Arrays.asList(rexBuilder.makeLiteral("HELLO"), rexBuilder.makeBigintLiteral(BigDecimal.ZERO), rexBuilder.makeBigintLiteral(BigDecimal.ZERO)));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlSubstringExpression);
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.OVERLAY, Arrays.asList(rexBuilder.makeLiteral("HELLO"), rexBuilder.makeLiteral("HELLO"), rexBuilder.makeBigintLiteral(BigDecimal.ZERO)));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlOverlayExpression);
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.OVERLAY, Arrays.asList(rexBuilder.makeLiteral("HELLO"), rexBuilder.makeLiteral("HELLO"), rexBuilder.makeBigintLiteral(BigDecimal.ZERO), rexBuilder.makeBigintLiteral(BigDecimal.ZERO)));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlOverlayExpression);
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.CASE, Arrays.asList(rexBuilder.makeLiteral(true), rexBuilder.makeLiteral("HELLO"), rexBuilder.makeLiteral("HELLO")));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlCaseExpression);
}

@Test
public void testBuildExpression_date() {
    RexNode rexNode;
    BeamSqlExpression exp;
    Calendar calendar = Calendar.getInstance();
    calendar.setTimeZone(TimeZone.getTimeZone("GMT"));
    calendar.setTime(new Date());
    // CEIL
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.CEIL, Arrays.asList(rexBuilder.makeDateLiteral(calendar), rexBuilder.makeFlag(TimeUnitRange.MONTH)));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlDateCeilExpression);
    // FLOOR
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.FLOOR, Arrays.asList(rexBuilder.makeDateLiteral(calendar), rexBuilder.makeFlag(TimeUnitRange.MONTH)));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlDateFloorExpression);
    // EXTRACT == EXTRACT_DATE?
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.EXTRACT, Arrays.asList(rexBuilder.makeFlag(TimeUnitRange.MONTH), rexBuilder.makeDateLiteral(calendar)));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlExtractExpression);
    // CURRENT_DATE
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.CURRENT_DATE, Arrays.<RexNode>asList());
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlCurrentDateExpression);
    // LOCALTIME
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.LOCALTIME, Arrays.<RexNode>asList());
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlCurrentTimeExpression);
    // LOCALTIMESTAMP
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.LOCALTIMESTAMP, Arrays.<RexNode>asList());
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlCurrentTimestampExpression);
    // DATETIME_PLUS
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.DATETIME_PLUS, Arrays.<RexNode>asList(rexBuilder.makeDateLiteral(calendar), rexBuilder.makeIntervalLiteral(new BigDecimal(10), new SqlIntervalQualifier(TimeUnit.DAY, TimeUnit.DAY, SqlParserPos.ZERO))));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlDatetimePlusExpression);
    // * for intervals
    rexNode = rexBuilder.makeCall(SqlStdOperatorTable.MULTIPLY, Arrays.<RexNode>asList(rexBuilder.makeExactLiteral(new BigDecimal(1)), rexBuilder.makeIntervalLiteral(new BigDecimal(10), new SqlIntervalQualifier(TimeUnit.DAY, TimeUnit.DAY, SqlParserPos.ZERO))));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlIntervalMultiplyExpression);
    // minus for dates
    rexNode = rexBuilder.makeCall(TYPE_FACTORY.createSqlType(SqlTypeName.INTERVAL_DAY), SqlStdOperatorTable.MINUS, Arrays.<RexNode>asList(rexBuilder.makeTimestampLiteral(Calendar.getInstance(), 1000), rexBuilder.makeTimestampLiteral(Calendar.getInstance(), 1000)));
    exp = BeamSqlFnExecutor.buildExpression(rexNode);
    assertTrue(exp instanceof BeamSqlDatetimeMinusExpression);
}

@Test
public void testAccept_normal() {
    List<BeamSqlExpression> operands = new ArrayList<>();
    // byte, short
    operands.add(BeamSqlPrimitive.of(SqlTypeName.TINYINT, Byte.valueOf("1")));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.SMALLINT, Short.MAX_VALUE));
    assertTrue(new BeamSqlPlusExpression(operands).accept());
    // integer, long
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 1));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.BIGINT, 1L));
    assertTrue(new BeamSqlPlusExpression(operands).accept());
    // float, double
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.FLOAT, 1.1F));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.DOUBLE, 1.1));
    assertTrue(new BeamSqlPlusExpression(operands).accept());
    // varchar
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.FLOAT, 1.1F));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "1"));
    assertFalse(new BeamSqlPlusExpression(operands).accept());
}

