    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, 1));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, -1));
    assertEquals("", new BeamSqlSubstringExpression(operands).evaluate(record, null).getValue());
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "hello"));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.INTEGER, -1));
    assertEquals("o", new BeamSqlSubstringExpression(operands).evaluate(record, null).getValue());
}

@Test
public void accept() throws Exception {
    List<BeamSqlExpression> operands = new ArrayList<>();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, " hello "));
    assertTrue(new BeamSqlTrimExpression(operands).accept());
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.SYMBOL, SqlTrimFunction.Flag.BOTH));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "he"));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "hehe__hehe"));
    assertTrue(new BeamSqlTrimExpression(operands).accept());
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "he"));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "hehe__hehe"));
    assertFalse(new BeamSqlTrimExpression(operands).accept());
}

@Test
public void evaluate() throws Exception {
    List<BeamSqlExpression> operands = new ArrayList<>();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.SYMBOL, SqlTrimFunction.Flag.LEADING));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "he"));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "hehe__hehe"));
    Assert.assertEquals("__hehe", new BeamSqlTrimExpression(operands).evaluate(record, null).getValue());
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.SYMBOL, SqlTrimFunction.Flag.TRAILING));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "he"));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "hehe__hehe"));
    Assert.assertEquals("hehe__", new BeamSqlTrimExpression(operands).evaluate(record, null).getValue());
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.SYMBOL, SqlTrimFunction.Flag.BOTH));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "he"));
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, "__"));
    Assert.assertEquals("__", new BeamSqlTrimExpression(operands).evaluate(record, null).getValue());
    operands.clear();
    operands.add(BeamSqlPrimitive.of(SqlTypeName.VARCHAR, " hello "));
    Assert.assertEquals("hello", new BeamSqlTrimExpression(operands).evaluate(record, null).getValue());
}

@Test
public void leadingTrim() throws Exception {
