@Test
public void testPendingStateCallsBlockTillCompletion() throws Exception {
    BeamFnApi.ProcessBundleDescriptor processBundleDescriptor = BeamFnApi.ProcessBundleDescriptor.newBuilder().putTransforms("2L", RunnerApi.PTransform.newBuilder().setSpec(RunnerApi.FunctionSpec.newBuilder().setUrn(DATA_INPUT_URN).build()).build()).setStateApiServiceDescriptor(ApiServiceDescriptor.getDefaultInstance()).build();
    Map<String, Message> fnApiRegistry = ImmutableMap.of("1L", processBundleDescriptor);
    CompletableFuture<StateResponse> successfulResponse = new CompletableFuture<>();
    CompletableFuture<StateResponse> unsuccessfulResponse = new CompletableFuture<>();
    BeamFnStateGrpcClientCache mockBeamFnStateGrpcClient = Mockito.mock(BeamFnStateGrpcClientCache.class);
    BeamFnStateClient mockBeamFnStateClient = Mockito.mock(BeamFnStateClient.class);
    when(mockBeamFnStateGrpcClient.forApiServiceDescriptor(any())).thenReturn(mockBeamFnStateClient);
    doAnswer(new Answer<Void>() {

        @Override
        public Void answer(InvocationOnMock invocation) throws Throwable {
            StateRequest.Builder stateRequestBuilder = (StateRequest.Builder) invocation.getArguments()[0];
            CompletableFuture<StateResponse> completableFuture = (CompletableFuture<StateResponse>) invocation.getArguments()[1];
            new Thread() {

                @Override
                public void run() {
                    // Simulate sleeping which introduces a race which most of the time requires
                    // the ProcessBundleHandler to block.
                    Uninterruptibles.sleepUninterruptibly(500, TimeUnit.MILLISECONDS);
                    switch(stateRequestBuilder.getInstructionReference()) {
                        case "SUCCESS":
                            completableFuture.complete(StateResponse.getDefaultInstance());
                            break;
                        case "FAIL":
                            completableFuture.completeExceptionally(new RuntimeException("TEST ERROR"));
                    }
                }
            }.start();
            return null;
        }
    }).when(mockBeamFnStateClient).handle(any(), any());
    ProcessBundleHandler handler = new ProcessBundleHandler(PipelineOptionsFactory.create(), fnApiRegistry::get, beamFnDataClient, mockBeamFnStateGrpcClient, ImmutableMap.of(DATA_INPUT_URN, new PTransformRunnerFactory<Object>() {

        @Override
        public Object createRunnerForPTransform(PipelineOptions pipelineOptions, BeamFnDataClient beamFnDataClient, BeamFnStateClient beamFnStateClient, String pTransformId, RunnerApi.PTransform pTransform, Supplier<String> processBundleInstructionId, Map<String, RunnerApi.PCollection> pCollections, Map<String, RunnerApi.Coder> coders, Multimap<String, ThrowingConsumer<WindowedValue<?>>> pCollectionIdsToConsumers, Consumer<ThrowingRunnable> addStartFunction, Consumer<ThrowingRunnable> addFinishFunction) throws IOException {
            addStartFunction.accept(() -> doStateCalls(beamFnStateClient));
            return null;
        }

        private void doStateCalls(BeamFnStateClient beamFnStateClient) {
            beamFnStateClient.handle(StateRequest.newBuilder().setInstructionReference("SUCCESS"), successfulResponse);
            beamFnStateClient.handle(StateRequest.newBuilder().setInstructionReference("FAIL"), unsuccessfulResponse);
        }
    }));
    handler.processBundle(BeamFnApi.InstructionRequest.newBuilder().setProcessBundle(BeamFnApi.ProcessBundleRequest.newBuilder().setProcessBundleDescriptorReference("1L")).build());
    assertTrue(successfulResponse.isDone());
    assertTrue(unsuccessfulResponse.isDone());
}

