}

@Test
public void testUsingUserState() throws Exception {
    String mainOutputId = "101";
    DoFnInfo<?, ?> doFnInfo = DoFnInfo.forFn(new TestStatefulDoFn(), WindowingStrategy.globalDefault(), ImmutableList.of(), KvCoder.of(StringUtf8Coder.of(), StringUtf8Coder.of()), Long.parseLong(mainOutputId), ImmutableMap.of(Long.parseLong(mainOutputId), new TupleTag<String>("mainOutput")));
    RunnerApi.FunctionSpec functionSpec = RunnerApi.FunctionSpec.newBuilder().setUrn(ParDoTranslation.CUSTOM_JAVA_DO_FN_URN).setPayload(ByteString.copyFrom(SerializableUtils.serializeToByteArray(doFnInfo))).build();
    RunnerApi.PTransform pTransform = RunnerApi.PTransform.newBuilder().setSpec(functionSpec).putInputs("input", "inputTarget").putOutputs(mainOutputId, "mainOutputTarget").build();
    FakeBeamFnStateClient fakeClient = new FakeBeamFnStateClient(ImmutableMap.of(key("value", "X"), encode("X0"), key("bag", "X"), encode("X0"), key("combine", "X"), encode("X0"), key("combineWithContext", "X"), encode("X0")));
    List<WindowedValue<String>> mainOutputValues = new ArrayList<>();
    Multimap<String, ThrowingConsumer<WindowedValue<?>>> consumers = HashMultimap.create();
    consumers.put("mainOutputTarget", (ThrowingConsumer) (ThrowingConsumer<WindowedValue<String>>) mainOutputValues::add);
    List<ThrowingRunnable> startFunctions = new ArrayList<>();
    List<ThrowingRunnable> finishFunctions = new ArrayList<>();
    new FnApiDoFnRunner.Factory<>().createRunnerForPTransform(PipelineOptionsFactory.create(), null, /* beamFnDataClient */
    fakeClient, TEST_PTRANSFORM_ID, pTransform, Suppliers.ofInstance("57L")::get, ImmutableMap.of(), ImmutableMap.of(), consumers, startFunctions::add, finishFunctions::add);
    Iterables.getOnlyElement(startFunctions).run();
    mainOutputValues.clear();
    assertThat(consumers.keySet(), containsInAnyOrder("inputTarget", "mainOutputTarget"));
    // Ensure that bag user state that is initially empty or populated works.
    // Ensure that the key order does not matter when we traverse over KV pairs.
    ThrowingConsumer<WindowedValue<?>> mainInput = Iterables.getOnlyElement(consumers.get("inputTarget"));
    mainInput.accept(valueInGlobalWindow(KV.of("X", "X1")));
    mainInput.accept(valueInGlobalWindow(KV.of("Y", "Y1")));
    mainInput.accept(valueInGlobalWindow(KV.of("X", "X2")));
    mainInput.accept(valueInGlobalWindow(KV.of("Y", "Y2")));
    assertThat(mainOutputValues, contains(valueInGlobalWindow("value:X0"), valueInGlobalWindow("bag:[X0]"), valueInGlobalWindow("combine:X0"), valueInGlobalWindow("combineWithContext:X0"), valueInGlobalWindow("value:null"), valueInGlobalWindow("bag:[]"), valueInGlobalWindow("combine:"), valueInGlobalWindow("combineWithContext:"), valueInGlobalWindow("value:X1"), valueInGlobalWindow("bag:[X0, X1]"), valueInGlobalWindow("combine:X0X1"), valueInGlobalWindow("combineWithContext:X0X1"), valueInGlobalWindow("value:Y1"), valueInGlobalWindow("bag:[Y1]"), valueInGlobalWindow("combine:Y1"), valueInGlobalWindow("combineWithContext:Y1")));
    mainOutputValues.clear();
    Iterables.getOnlyElement(finishFunctions).run();
    assertThat(mainOutputValues, empty());
    assertEquals(ImmutableMap.<StateKey, ByteString>builder().put(key("value", "X"), encode("X2")).put(key("bag", "X"), encode("X0", "X1", "X2")).put(key("combine", "X"), encode("X0X1X2")).put(key("combineWithContext", "X"), encode("X0X1X2")).put(key("value", "Y"), encode("Y2")).put(key("bag", "Y"), encode("Y1", "Y2")).put(key("combine", "Y"), encode("Y1Y2")).put(key("combineWithContext", "Y"), encode("Y1Y2")).build(), fakeClient.getData());
    mainOutputValues.clear();
}

