public void testAppend() throws Exception {
    FakeBeamFnStateClient fakeClient = new FakeBeamFnStateClient(ImmutableMap.of(key("A"), encode("A1")));
    BagUserState<String> userState = new BagUserState<>(fakeClient, "A", StringUtf8Coder.of(), () -> requestForId("A"));
