@Test
public void testReadWithParser() throws Exception {
    PCollection<KV<String, Integer>> output = pipeline.apply(MongoDbGridFSIO.<KV<String, Integer>>read().withUri("mongodb://localhost:" + port).withDatabase(DATABASE).withBucket("mapBucket").withParser(new MongoDbGridFSIO.Parser<KV<String, Integer>>() {

        @Override
        public void parse(GridFSDBFile input, MongoDbGridFSIO.ParserCallback<KV<String, Integer>> callback) throws IOException {
            try (final BufferedReader reader = new BufferedReader(new InputStreamReader(input.getInputStream()))) {
                String line = reader.readLine();
                while (line != null) {
                    try (Scanner scanner = new Scanner(line.trim())) {
                        scanner.useDelimiter("\\t");
                        long timestamp = scanner.nextLong();
                        String name = scanner.next();
                        int score = scanner.nextInt();
                        callback.output(KV.of(name, score), new Instant(timestamp));
                    }
                    line = reader.readLine();
                }
            }
        }
    }).withSkew(new Duration(3610000L)).withCoder(KvCoder.of(StringUtf8Coder.of(), VarIntCoder.of())));
    PAssert.thatSingleton(output.apply("Count All", Count.<KV<String, Integer>>globally())).isEqualTo(50100L);
    PAssert.that(output.apply("Max PerElement", Max.<String>integersPerKey())).satisfies(new SerializableFunction<Iterable<KV<String, Integer>>, Void>() {

        @Override
        public Void apply(Iterable<KV<String, Integer>> input) {
            for (KV<String, Integer> element : input) {
                assertEquals(101, element.getValue().longValue());
            }
            return null;
        }
    });
    pipeline.run();
}

@Test
public void testSplit() throws Exception {
    PipelineOptions options = PipelineOptionsFactory.create();
    MongoDbGridFSIO.Read<String> read = MongoDbGridFSIO.<String>read().withUri("mongodb://localhost:" + port).withDatabase(DATABASE);
    BoundedGridFSSource src = new BoundedGridFSSource(read, null);
    // make sure 2 files can fit in
    long desiredBundleSizeBytes = (src.getEstimatedSizeBytes(options) * 2L) / 5L + 1000;
    List<? extends BoundedSource<ObjectId>> splits = src.split(desiredBundleSizeBytes, options);
    int expectedNbSplits = 3;
    assertEquals(expectedNbSplits, splits.size());
    SourceTestUtils.assertSourcesEqualReferenceSource(src, splits, options);
    int nonEmptySplits = 0;
    int count = 0;
    for (BoundedSource<ObjectId> subSource : splits) {
        List<ObjectId> result = SourceTestUtils.readFromSource(subSource, options);
        if (result.size() > 0) {
            nonEmptySplits += 1;
        }
        count += result.size();
    }
    assertEquals(expectedNbSplits, nonEmptySplits);
    assertEquals(5, count);
}

@Test
public void testWriteMessage() throws Exception {
    ArrayList<String> data = new ArrayList<>(100);
    ArrayList<Integer> intData = new ArrayList<>(100);
    for (int i = 0; i < 1000; i++) {
        data.add("Message " + i);
    }
    for (int i = 0; i < 100; i++) {
        intData.add(i);
    }
    pipeline.apply("String", Create.of(data)).apply("StringInternal", MongoDbGridFSIO.write().withUri("mongodb://localhost:" + port).withDatabase(DATABASE).withChunkSize(100L).withBucket("WriteTest").withFilename("WriteTestData"));
    pipeline.apply("WithWriteFn", Create.of(intData)).apply("WithWriteFnInternal", MongoDbGridFSIO.write(new WriteFn<Integer>() {

        @Override
        public void write(Integer output, OutputStream outStream) throws IOException {
            //one byte per output
            outStream.write(output.byteValue());
        }
    }).withUri("mongodb://localhost:" + port).withDatabase(DATABASE).withBucket("WriteTest").withFilename("WriteTestIntData"));
    pipeline.run();
    Mongo client = null;
    try {
        StringBuilder results = new StringBuilder();
        client = new Mongo("localhost", port);
        DB database = client.getDB(DATABASE);
        GridFS gridfs = new GridFS(database, "WriteTest");
        List<GridFSDBFile> files = gridfs.find("WriteTestData");
        assertTrue(files.size() > 0);
        for (GridFSDBFile file : files) {
            assertEquals(100, file.getChunkSize());
            int l = (int) file.getLength();
            try (InputStream ins = file.getInputStream()) {
                DataInputStream dis = new DataInputStream(ins);
                byte[] b = new byte[l];
                dis.readFully(b);
                results.append(new String(b, "utf-8"));
            }
        }
        String dataString = results.toString();
        for (int x = 0; x < 1000; x++) {
            assertTrue(dataString.contains("Message " + x));
        }
        files = gridfs.find("WriteTestIntData");
        boolean[] intResults = new boolean[100];
        for (GridFSDBFile file : files) {
            int l = (int) file.getLength();
            try (InputStream ins = file.getInputStream()) {
                DataInputStream dis = new DataInputStream(ins);
                byte[] b = new byte[l];
                dis.readFully(b);
                for (int x = 0; x < b.length; x++) {
                    intResults[b[x]] = true;
                }
            }
        }
        for (int x = 0; x < 100; x++) {
            assertTrue("Did not get a result for " + x, intResults[x]);
        }
    } finally {
        if (client != null) {
            client.close();
        }
    }
}

