    PCollection<String> dupes = p.apply(Create.of("foo", "foos", "barbaz", "barbaz", "bazbar", "foo"));
    PCollection<String> deduped = dupes.apply(Distinct.withRepresentativeValueFn((String s) -> s.length()).withRepresentativeType(TypeDescriptor.of(Integer.class)));
    PAssert.that(deduped).satisfies((Iterable<String> strs) -> {
        Set<Integer> seenLengths = new HashSet<>();
        for (String s : strs) {
            assertThat(predupedContents.values(), hasItem(s));
            assertThat(seenLengths, not(contains(s.length())));
            seenLengths.add(s.length());
        }
        return null;
    });
    p.run();
}

